SELECT CASE WHEN price >= 1310 THEN 'LARGE' ELSE 'SMALL' END AS price_tier, CASE WHEN cost >= 720 THEN 'HIGH' ELSE 'LOW' END AS cost_tier, ROUND(SUM(stock_qty) / NULLIF(COUNT(CASE WHEN brand = 'Umbrella' THEN 1 END), 0), 2) AS stock_qty_per_umbrella, SUM(CASE WHEN category = 'Books' THEN cost ELSE 0 END) AS books_cost, ROUND(SUM(price) / NULLIF(COUNT(CASE WHEN brand = 'Globex' THEN 1 END), 0), 2) AS price_per_globex, CORR(cost, price) AS corr_cost_price, GROUPING_ID() AS grouping_id FROM products GROUP BY GROUPING SETS ((CASE WHEN price >= 1310 THEN 'LARGE' ELSE 'SMALL' END, CASE WHEN cost >= 720 THEN 'HIGH' ELSE 'LOW' END), (CASE WHEN price >= 1310 THEN 'LARGE' ELSE 'SMALL' END), ())
